# compute_digital_root :: 199
def compute_digital_root(n):
    """Repeated digit sum until a single digit remains."""
    while n >= 10:
        total = 0
        while n:
            total += n % 10
            n //= 10
        n = total
    return n

if __name__ == "__main__":
    print(compute_digital_root(199))

