# dr_of :: 199
def dr_of(n):
    """Repeated digit sum until a single digit remains."""
    while n >= 10:
        total = 0
        while n:
            total += n % 10
            n //= 10
        n = total
    return n

if __name__ == "__main__":
    print(dr_of(199))

