# volume_of_sphere :: 0.5
def volume_of_sphere(r):
    """Volume of a sphere with radius r."""
    return 4 / 3 * 3.141592653589793 * r ** 3

if __name__ == "__main__":
    print(volume_of_sphere(0.5))

# volume_of_cone :: 2.5, 3
def volume_of_cone(r, h):
    """Volume of a cone with radius r and height h."""
    return 3.141592653589793 * r ** 2 * h / 3

if __name__ == "__main__":
    print(volume_of_cone(2.5, 3))

