# single_interior_angle :: 6
def single_interior_angle(sides):
    """Interior angle at each vertex of a regular polygon."""
    return (sides - 2) * 180 / sides

if __name__ == "__main__":
    print(single_interior_angle(6))

# growth_percent :: 10000, 0, 7
def growth_percent(principal, rate, years):
    """Total after compounding principal at rate% per year for years."""
    return principal * (1 + rate / 100) ** years

if __name__ == "__main__":
    print(growth_percent(10000, 0, 7))

